    !---------------------------------------------
    ! rocblas_pointer_to_mode
    !---------------------------------------------
    !> \brief  Indicates whether the pointer is on the host or device.
    function rocblas_pointer_to_mode(ptr) &
       result(pointer_to_mode) &
       bind(C, name="rocblas_pointer_to_mode")
       import :: c_ptr, c_int
       type(c_ptr), value :: ptr
       integer(c_int) :: pointer_to_mode
    end function rocblas_pointer_to_mode

    !---------------------------------------------
    ! rocblas_set_vector
    !---------------------------------------------
    !> \brief Copy vector from host to device.
    !> @param[in]
    !> n           [rocblas_int]
    !> number of elements in the vector
    !> @param[in]
    !> elem_size   [rocblas_int]
    !> number of bytes per element in the matrix
    !> @param[in]
    !> x           pointer to vector on the host
    !> @param[in]
    !> incx        [rocblas_int]
    !> specifies the increment for the elements of the vector
    !> @param[out]
    !> y           pointer to vector on the device
    !> @param[in]
    !> incy        [rocblas_int]
    !> specifies the increment for the elements of the vector
    function rocblas_set_vector(n, elem_size, x, incx, y, incy) &
       result(set_vector) &
       bind(C, name="rocblas_set_vector")
       import :: c_int, c_ptr
       integer(c_int), value :: n
       integer(c_int), value :: elem_size
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       type(c_ptr), value :: y
       integer(c_int), value :: incy
       integer(c_int) :: set_vector
    end function rocblas_set_vector

