    !---------------------------------------------
    ! rocblas_set_vector_async
    !---------------------------------------------
    !> \brief Asynchronously copy vector from host to device.
    !> \details
    !> ``rocblas_set_vector_async`` copies a vector from pinned host memory to device memory
    !> asynchronously.
    !> Memory on the host must be allocated with ``hipHostMalloc`` or the transfer will be
    !> synchronous.
    !> @param[in]
    !> n           [rocblas_int]
    !> number of elements in the vector
    !> @param[in]
    !> elem_size   [rocblas_int]
    !> number of bytes per element in the matrix
    !> @param[in]
    !> x           pointer to vector on the host
    !> @param[in]
    !> incx        [rocblas_int]
    !> specifies the increment for the elements of the vector
    !> @param[out]
    !> y           pointer to vector on the device
    !> @param[in]
    !> incy        [rocblas_int]
    !> specifies the increment for the elements of the vector
    !> @param[in]
    !> stream      specifies the stream into which this transfer request is queued
    function rocblas_set_vector_async(n, elem_size, x, incx, y, incy, stream) &
       result(set_vector_async) &
       bind(C, name="rocblas_set_vector_async")
       import :: c_int, c_ptr
       integer(c_int), value :: n
       integer(c_int), value :: elem_size
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       type(c_ptr), value :: y
       integer(c_int), value :: incy
       type(c_ptr), value :: stream
       integer(c_int) :: set_vector_async
    end function rocblas_set_vector_async

    !---------------------------------------------
    ! rocblas_set_vector_async_64
    !---------------------------------------------
