       bind(C, name="rocblas_set_vector_async_64")
       import :: c_long, c_ptr, c_int
       integer(c_long), value :: n
       integer(c_long), value :: elem_size
       type(c_ptr), value :: x
       integer(c_long), value :: incx
       type(c_ptr), value :: y
       integer(c_long), value :: incy
       type(c_ptr), value :: stream
       integer(c_int) :: set_vector_async_64
    end function rocblas_set_vector_async_64

    !---------------------------------------------
    ! rocblas_get_vector_async
