  interface rocblas_scopy_batched
    !---------------------------------------------
    ! rocblas_scopy_batched
    !---------------------------------------------
    !> \brief  BLAS Level 1 API
    !>
    !> \details
    !> The copy_batched functions copy each element ``x_i[j]`` into ``y_i[j]``, for ``j`` = 1 , ...
    !> , ``n``; ``i`` = 1 , ... , ``batch_count``:
    !>
    !> y_i := x_i,
    !>
    !> where (``x_i``, ``y_i``) is the i-th instance of the batch and
    !> ``x_i`` and``y_i`` are vectors.
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocBLAS library context queue.
    !> @param[in]
    !> n         [rocblas_int]
    !> the number of elements in each x_i to be copied to y_i.
    !> @param[in]
    !> x         device array of device pointers storing each vector x_i.
    !> @param[in]
    !> incx      [rocblas_int]
    !> specifies the increment for the elements of each vector x_i.
    !> @param[out]
    !> y         device array of device pointers storing each vector y_i.
    !> @param[in]
    !> incy      [rocblas_int]
    !> specifies the increment for the elements of each vector y_i.
    !> @param[in]
    !> batch_count [rocblas_int]
    !> number of instances in the batch.
    function rocblas_scopy_batched_raw(handle, n, x, incx, y, incy, batch_count) &
       result(scopy_batched_raw) &
       bind(C, name="rocblas_scopy_batched")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: n
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       type(c_ptr), value :: y
       integer(c_int), value :: incy
       integer(c_int), value :: batch_count
       integer(c_int) :: scopy_batched_raw
    end function rocblas_scopy_batched_raw

    module procedure rocblas_scopy_batched_typed
  end interface rocblas_scopy_batched

