  interface rocblas_ssymm
    !---------------------------------------------
    ! rocblas_ssymm
    !---------------------------------------------
    !> \brief  BLAS Level 3 API
    !>
    !> \details
    !> The symm functions perform one of the matrix-matrix operations:
    !>
    !> C := alpha*A*B + beta*C if side == rocblas_side_left,
    !> C := alpha*B*A + beta*C if side == rocblas_side_right,
    !>
    !> where ``alpha`` and ``beta`` are scalars, ``B`` and ``C`` are ``m`` by ``n`` matrices, and
    !> ``A`` is a symmetric matrix stored as either upper or lower.
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocBLAS library context queue.
    !>
    !> @param[in]
    !> side  [rocblas_side]
    !> - rocblas_side_left:      C := alpha*A*B + beta*C
    !> - rocblas_side_right:     C := alpha*B*A + beta*C
    !>
    !> @param[in]
    !> uplo    [rocblas_fill]
    !> - rocblas_fill_upper:  A is an upper triangular matrix
    !> - rocblas_fill_lower:  A is a  lower triangular matrix
    !>
    !> @param[in]
    !> m       [rocblas_int]
    !> m specifies the number of rows of B and C. m >= 0.
    !>
    !> @param[in]
    !> n       [rocblas_int]
    !> n specifies the number of columns of B and C. n >= 0.
    !>
    !> @param[in]
    !> alpha
    !> alpha specifies the scalar alpha. When alpha is
    !> zero, A and B are not referenced.
    !>
    !> @param[in]
    !> A       pointer storing matrix A on the GPU.
    !> - A is m by m if side == rocblas_side_left.
    !> - A is n by n if side == rocblas_side_right.
    !> - Only the upper/lower triangular part is accessed.
    !>
    !> @param[in]
    !> lda     [rocblas_int]
    !> lda specifies the first dimension of A.
    !> - If side = rocblas_side_left,  lda >= max( 1, m ).
    !> - Otherwise, lda >= max( 1, n ).
    !>
    !> @param[in]
    !> B       pointer storing matrix B on the GPU.
    !> Matrix dimension is m by n.
    !>
    !> @param[in]
    !> ldb     [rocblas_int]
    !> ldb specifies the first dimension of B. ldb >= max( 1, m ).
    !>
    !> @param[in]
    !> beta
    !> beta specifies the scalar beta. When beta is
    !> zero, then C need not be set before entry.
    !>
    !> @param[in]
    !> C       pointer storing matrix C on the GPU.
    !> Matrix dimension is m by n.
    !>
    !> @param[in]
    !> ldc    [rocblas_int]
    !> ldc specifies the first dimension of C. ldc >= max( 1, m ).
    function rocblas_ssymm_raw(handle, side, uplo, m, n, alpha, A, lda, B, ldb, beta, C, ldc) &
       result(ssymm_raw) &
       bind(C, name="rocblas_ssymm")
       import :: c_ptr, c_int, c_float
       type(c_ptr), value :: handle
       integer(c_int), value :: side
       integer(c_int), value :: uplo
       integer(c_int), value :: m
       integer(c_int), value :: n
       real(c_float) :: alpha
       type(c_ptr), value :: A
       integer(c_int), value :: lda
       type(c_ptr), value :: B
       integer(c_int), value :: ldb
       real(c_float) :: beta
       type(c_ptr), value :: C
       integer(c_int), value :: ldc
       integer(c_int) :: ssymm_raw
    end function rocblas_ssymm_raw

    module procedure rocblas_ssymm_native
    module procedure rocblas_ssymm_typed
  end interface rocblas_ssymm

