  end interface rocblas_herk_ex

  interface rocblas_axpy_ex
    !---------------------------------------------
    ! rocblas_axpy_ex
    !---------------------------------------------
    !> \brief  BLAS EX API
    !>
    !> \details
    !> axpy_ex   computes constant alpha multiplied by vector x, plus vector y.
    !>
    !> y := alpha * x + y
    !>
    !> Currently supported datatypes are as follows:
    !>
    !> -------------------------------------------------
    !> | alpha_type | x_type | y_type | execution_type |
    !> |------------|--------|--------|----------------|
    !> |  bf16_r    | bf16_r |  bf16_r|      f32_r     |
    !> |  f32_r     | bf16_r |  bf16_r|      f32_r     |
    !> |  f16_r     | f16_r  |  f16_r |      f16_r     |
    !> |  f16_r     | f16_r  |  f16_r |      f32_r     |
    !> |  f32_r     | f16_r  |  f16_r |      f32_r     |
    !> |  f32_r     | f32_r  |  f32_r |      f32_r     |
    !> |  f64_r     | f64_r  |  f64_r |      f64_r     |
    !> |  f32_c     | f32_c  |  f32_c |      f32_c     |
    !> |  f64_c     | f64_c  |  f64_c |      f64_c     |
    !> -------------------------------------------------
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocblas library context queue.
    !> @param[in]
    !> n         [rocblas_int]
    !> the number of elements in x and y.
    !> @param[in]
    !> alpha     device pointer or host pointer to specify the scalar alpha.
    !> @param[in]
    !> alpha_type [rocblas_datatype]
    !> specifies the datatype of alpha.
    !> @param[in]
    !> x         device pointer storing vector x.
    !> @param[in]
    !> x_type [rocblas_datatype]
    !> specifies the datatype of vector x.
    !> @param[in]
    !> incx      [rocblas_int]
    !> specifies the increment for the elements of x.
    !> @param[in, out]
    !> y         device pointer storing vector y.
    !> @param[in]
    !> y_type [rocblas_datatype]
    !> specifies the datatype of vector y.
    !> @param[in]
    !> incy      [rocblas_int]
    !> specifies the increment for the elements of y.
    !> @param[in]
    !> execution_type [rocblas_datatype]
    !> specifies the datatype of computation.
    function rocblas_axpy_ex_raw(handle, n, alpha, alpha_type, x, x_type, incx, y, y_type, incy, &
                                 execution_type) &
       result(axpy_ex_raw) &
       bind(C, name="rocblas_axpy_ex")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: n
       type(c_ptr), value :: alpha
       integer(c_int), value :: alpha_type
       type(c_ptr), value :: x
       integer(c_int), value :: x_type
       integer(c_int), value :: incx
       type(c_ptr), value :: y
       integer(c_int), value :: y_type
       integer(c_int), value :: incy
       integer(c_int), value :: execution_type
       integer(c_int) :: axpy_ex_raw
    end function rocblas_axpy_ex_raw

    module procedure rocblas_axpy_ex_typed
  end interface rocblas_axpy_ex

  interface rocblas_axpy_ex_64
    !---------------------------------------------
    ! rocblas_axpy_ex_64
    !---------------------------------------------
    function rocblas_axpy_ex_64_raw(handle, n, alpha, alpha_type, x, x_type, incx, y, y_type, &
                                    incy, execution_type) &
       result(axpy_ex_64_raw) &
