  interface rocblas_set_device_memory_size
    !---------------------------------------------
    ! rocblas_set_device_memory_size
    !---------------------------------------------
    !> \brief
    !> \details
    !> Changes the size of allocated device memory at runtime.
    !>
    !> Any previously allocated device memory managed by the handle is freed.
    !>
    !> If size > 0 sets the device memory size to the specified size (in bytes).
    !> If size == 0, frees the memory allocated so far, and lets rocBLAS manage device memory in the
    !> future, expanding it when necessary.
    !> Returns rocblas_status_invalid_handle if handle is nullptr; rocblas_status_invalid_pointer if
    !> size is nullptr; rocblas_status_success otherwise
    !> @param[in]
    !> handle          rocblas handle
    !> @param[in]
    !> size            size of allocated device memory
    function rocblas_set_device_memory_size_raw(handle, size) &
       result(set_device_memory_size_raw) &
       bind(C, name="rocblas_set_device_memory_size")
       import :: c_ptr, c_long, c_int
       type(c_ptr), value :: handle
       integer(c_long), value :: size
       integer(c_int) :: set_device_memory_size_raw
    end function rocblas_set_device_memory_size_raw

    module procedure rocblas_set_device_memory_size_typed
  end interface rocblas_set_device_memory_size

